const $=s=>document.querySelector(s);const names=['C','C♯','D','E♭','E','F','F♯','G','A♭','A','B♭','B'];const tuning=[40,45,50,55,59,64];const strings=['E','A','D','G','B','e'];const scales={major:{name:'Maior natural',i:[0,2,4,5,7,9,11],d:['1','2','3','4','5','6','7'],tone:'T · T · S · T · T · T · S'},minor:{name:'Menor natural',i:[0,2,3,5,7,8,10],d:['1','2','♭3','4','5','♭6','♭7'],tone:'T · S · T · T · S · T · T'},pmin:{name:'Pentatônica menor',i:[0,3,5,7,10],d:['1','♭3','4','5','♭7']},pmaj:{name:'Pentatônica maior',i:[0,2,4,7,9],d:['1','2','3','5','6']},hmin:{name:'Menor harmônica',i:[0,2,3,5,7,8,11],d:['1','2','♭3','4','5','♭6','7']},hmaj:{name:'Maior harmônica',i:[0,2,4,5,7,8,11],d:['1','2','3','4','5','♭6','7']},ion:{name:'Jônio',i:[0,2,4,5,7,9,11],d:['1','2','3','4','5','6','7']},dor:{name:'Dórico',i:[0,2,3,5,7,9,10],d:['1','2','♭3','4','5','6','♭7']},phr:{name:'Frígio',i:[0,1,3,5,7,8,10],d:['1','♭2','♭3','4','5','♭6','♭7']},lyd:{name:'Lídio',i:[0,2,4,6,7,9,11],d:['1','2','3','♯4','5','6','7']},mix:{name:'Mixolídio',i:[0,2,4,5,7,9,10],d:['1','2','3','4','5','6','♭7']},aeo:{name:'Eólio',i:[0,2,3,5,7,8,10],d:['1','2','♭3','4','5','♭6','♭7']},loc:{name:'Lócrio',i:[0,1,3,5,6,8,10],d:['1','♭2','♭3','4','♭5','♭6','♭7']},tri:{name:'Tríade maior',i:[0,4,7],d:['1','3','5']},trimin:{name:'Tríade menor',i:[0,3,7],d:['1','♭3','5']},maj7:{name:'Arpejo maior com 7ª',i:[0,4,7,11],d:['1','3','5','7']},min7:{name:'Arpejo menor com 7ª',i:[0,3,7,10],d:['1','♭3','5','♭7']},dom7:{name:'Arpejo dominante',i:[0,4,7,10],d:['1','3','5','♭7']},blues:{name:'Blues menor',i:[0,3,5,6,7,10],d:['1','♭3','4','♭5','5','♭7']}};
const chapters=[
{title:'Escalas maiores e menores',short:'A base de tudo: intervalos, tonalidades e os primeiros caminhos pelo braço.',level:'Fundamentos',types:['major','minor'],intro:'Sete notas, muitas possibilidades. Entenda a construção das escalas e encontre a tônica em qualquer região do instrumento.',theory:[['Uma escala é uma organização de intervalos','Um semitom (S) equivale a uma casa; um tom (T), a duas. A escala maior organiza os intervalos em T–T–S–T–T–T–S. A menor natural usa T–S–T–T–S–T–T. A fórmula é sempre medida em relação à tônica.'],['Relativas e paralelas','C maior e A menor natural compartilham as mesmas notas, mas têm centros diferentes. A relativa menor fica três semitons abaixo da tônica maior. C maior e C menor são paralelas: mesma tônica, notas diferentes. Toque e sustente a tônica para ouvir essa diferença.'],['Transforme o desenho em música','Localize as tônicas antes de tocar. Suba a escala dizendo os nomes das notas; depois desça dizendo os graus. Crie uma frase de quatro notas e termine em 1, 3 ou 5 sobre um acorde maior. Na menor, experimente 1, ♭3 e 5.']],application:'Em C maior, improvise sobre C–F–G–C. Em A menor, use Am–Dm–Em–Am. Comece com duas notas por acorde e faça pausas.',drills:['Suba e desça uma região com palhetada alternada, a 60 BPM, uma nota por clique.','Toque em terças: 1–3, 2–4, 3–5. Cante antes de tocar.','Conecte duas regiões por uma nota em comum, sem parar o pulso.'],goal:'Reconhecer a tônica, explicar T e S e tocar maior e menor sem perder o pulso.'},
{title:'Pentatônicas maior e menor',short:'Cinco notas, cinco regiões e um vocabulário inteiro para criar solos.',level:'Essencial',types:['pmin','pmaj'],intro:'O vocabulário que atravessa o blues, o rock, o pop e o country. Conecte os cinco boxes e comece a frasear.',theory:[['O que sai e o que fica','A pentatônica maior contém 1–2–3–5–6: retira 4 e 7 da maior natural. A menor contém 1–♭3–4–5–♭7: retira 2 e ♭6 da menor natural. Não confunda uma fórmula com a outra.'],['Cinco boxes, um único braço','Cada box é uma região da mesma coleção de notas. As bordas se sobrepõem; uma nota pode ser o ponto de partida de um slide. Os cinco boxes tradicionais da menor estão disponíveis no laboratório; o mapa maior mostra cinco janelas móveis para explorar a mesma escala.'],['Maior e menor relativas','A menor pentatônica e C maior pentatônica compartilham A, C, D, E e G. O desenho não determina sozinho a sensação: a harmonia e a nota de repouso definem o centro. Sobre Am, resolva em A; sobre C, em C.']],application:'Sobre Am7, crie uma pergunta de dois tempos e uma resposta de dois tempos. Use repetição, silêncio e uma nota final longa. Depois experimente a maior pentatônica sobre um acorde maior da mesma tônica.',drills:['Toque os cinco boxes lentamente, identificando todas as tônicas.','Faça grupos de três notas, mantendo acentos a cada quatro.','Crie três frases usando apenas 1, ♭3 e 4; acrescente 5 e ♭7 depois.'],goal:'Conectar dois boxes e criar uma frase de quatro compassos com pausas.'},
{title:'Escalas harmônicas',short:'A tensão da sétima maior e as cores da sexta menor.',level:'Intermediário',types:['hmin','hmaj'],intro:'Explore a menor harmônica e a maior harmônica, entendendo as alterações que dão personalidade a cada uma.',theory:[['Menor harmônica: a sensível','Eleve a ♭7 da menor natural para 7. Em A: A–B–C–D–E–F–G♯. Essa alteração permite o acorde E maior ou E7 no tom de A menor. O intervalo entre ♭6 e 7 tem três semitons: uma segunda aumentada.'],['Maior harmônica: uma cor diferente','A maior harmônica é a escala maior com ♭6. Em C: C–D–E–F–G–A♭–B. O contraste entre 3 maior e ♭6 é sua identidade. Não é a relativa maior da menor harmônica.'],['Ouça a resolução','Na menor harmônica, toque 7–1 e perceba a atração da sensível. Sobre V7–i, use 7 da escala como 3ª do acorde dominante. Na maior harmônica, experimente a cor do iv menor voltando ao I maior.']],application:'Em A menor, use Dm–E7–Am e destaque G♯ sobre E7, resolvendo em A. Em C maior harmônica, toque Fm–C e ouça A♭ descendo para G.',drills:['Compare menor natural e harmônica alterando apenas a sétima.','Toque ♭6–7–1 devagar e sem esticar a mão além do confortável.','Grave uma frase sobre V7–i, destacando a sensível antes da resolução.'],goal:'Ouvir e localizar a 7ª maior na menor harmônica e a ♭6 na maior harmônica.'},
{title:'Sistema CAGED',short:'Cinco formas de acorde para enxergar o braço como um mapa conectado.',level:'Essencial',types:['tri','trimin'],intro:'C, A, G, E e D são formas de acordes. Ao movê-las, você conecta tônicas, tríades e escalas ao longo do braço.',theory:[['A forma não é o nome do acorde','Uma forma de E deslocada por pestana pode soar F, G ou A. O nome vem da tônica. O ciclo C–A–G–E–D descreve a ordem das formas ao subir o braço para o mesmo acorde.'],['Enxergue as tônicas','Nas formas E e G há tônicas na 6ª corda; nas formas A e C, na 5ª; na forma D, na 4ª. Identifique primeiro esse ponto de referência. Algumas formas completas são desconfortáveis: use fragmentos de três ou quatro cordas.'],['Do acorde para a escala','Toque o acorde, destaque sua tríade e preencha com a escala. Assim, os graus 1, 3 e 5 viram pontos de repouso. O mapa de tríades do laboratório mostra essas notas; a tabela abaixo traz cinco formas concretas de C maior.']],application:'Toque C maior em cada forma da tabela. Depois improvise uma pequena frase perto do acorde e termine em uma de suas notas.',drills:['Toque cada forma de C e diga em voz alta onde estão as tônicas.','Escolha só três cordas de cada forma e conecte as vozes pelo menor deslocamento.','Faça C–F–G em uma região usando fragmentos, sem voltar sempre às cordas soltas.'],goal:'Encontrar o mesmo acorde em cinco regiões e conectar uma tríade à escala.'},
{title:'Modos gregos',short:'Sete maneiras de organizar a escuta. Descubra as notas que dão cor a cada modo.',level:'Intermediário',types:['ion','dor','phr','lyd','mix','aeo','loc'],intro:'Mais que começar uma escala em outra nota: estudar modos é estabelecer um centro e ouvir suas notas características.',theory:[['Centro tonal vem primeiro','D dórico usa as notas de C maior, mas D precisa soar como centro. Tocar as mesmas notas sobre C maior ainda tende a soar C jônio. Use um pedal ou acorde sustentado da tônica para comparar modos paralelos.'],['As cores dos modos','Jônio: 7 maior. Dórico: menor com 6 maior. Frígio: menor com ♭2. Lídio: maior com ♯4. Mixolídio: maior com ♭7. Eólio: menor com ♭6. Lócrio: ♭2 e ♭5; sua tríade diminuta oferece pouca estabilidade.'],['Compare sem trocar a tônica','Mantenha A como centro: compare A eólio e A dórico mudando apenas F para F♯. Depois compare C jônio e C lídio, trocando F por F♯. Uma diferença pequena produz uma mudança clara de cor.']],application:'Dórico: Dm7 com 6 maior B; lídio: Cmaj7 com F♯; mixolídio: G7 com F. Sustente o acorde e toque frases curtas, evidenciando a nota característica.',drills:['Toque os sete modos com a mesma tônica, ouvindo as diferenças.','Crie uma frase que destaque a nota característica e resolva na tônica.','Compare dórico/eólio e jônio/lídio sem olhar o braço.'],goal:'Identificar a cor de dórico, lídio e mixolídio sobre um centro estável.'},
{title:'Tríades e arpejos',short:'As notas dos acordes viram linhas melódicas, inversões e pontos de chegada.',level:'Intermediário',types:['tri','trimin','maj7','min7','dom7'],intro:'Ouça os acordes por dentro. Aprenda a destacar suas notas e conectar melodias à harmonia.',theory:[['Três notas essenciais','Tríade maior: 1–3–5. Menor: 1–♭3–5. A terça define a qualidade. Toque as notas juntas como acorde e separadas como arpejo; o conjunto de alturas é o mesmo.'],['Inversões e condução de vozes','Posição fundamental tem 1 no baixo; primeira inversão, 3; segunda, 5. Em C: C–E–G, E–G–C, G–C–E. Em uma progressão, procure mover cada nota para a nota mais próxima do próximo acorde.'],['Acrescente a sétima','Maj7: 1–3–5–7; m7: 1–♭3–5–♭7; dominante: 1–3–5–♭7. Compare Cmaj7 e C7: uma única nota muda. No dominante, 3 e ♭7 formam o trítono que pede resolução.']],application:'Em Dm7–G7–Cmaj7, procure as notas-guia: F e C; B e F; E e B. Conecte C→B e F→E para ouvir a resolução.',drills:['Toque tríades maiores e menores nas três cordas agudas.','Arpeje 1–3–5–7 e volte 7–5–3–1 em várias tônicas.','Em um ii–V–I, toque apenas terças e sétimas antes de preencher as frases.'],goal:'Distinguir maior, menor e dominante e resolver uma frase em uma nota do acorde.'},
{title:'Blues e expressão',short:'Blue notes, bends, vibrato e frases que respiram.',level:'Aplicação',types:['blues','pmin','pmaj'],intro:'Transforme poucas notas em intenção. Trabalhe afinação, articulação e a conversa entre pergunta e resposta.',theory:[['A blue note','A escala blues menor acrescenta ♭5 à pentatônica menor: 1–♭3–4–♭5–5–♭7. Use a ♭5 como passagem, por exemplo 4–♭5–5; sustentar a tensão deve ser uma escolha consciente.'],['Bend afinado, vibrato controlado','Toque a nota de destino antes de fazer o bend. Para um bend de um tom, compare com a nota duas casas acima. Use dedos de apoio e mantenha o gesto confortável. No vibrato, ouça a largura e a regularidade.'],['A forma de doze compassos','Uma forma básica usa I7 por quatro compassos, IV7 por dois, I7 por dois, V7 por um, IV7 por um e I7 por dois. Há variações, como V7 no último compasso para voltar ao início.']],application:'Em A: A7 | A7 | A7 | A7 | D7 | D7 | A7 | A7 | E7 | D7 | A7 | E7. A pentatônica menor cria tensão contra a 3ª maior dos acordes; experimente resolver C em C♯ sobre A7.',drills:['Faça 4–♭5–5 com três articulações: palheta, ligado e slide.','Toque uma frase de um compasso e responda com uma variação.','Faça cinco bends, comparando cada um com a nota de destino.'],goal:'Afinar um bend de um tom e construir frases que respeitem os doze compassos.'},
{title:'Técnica e improvisação',short:'Sincronia, ritmo e criação para transformar estudo em música.',level:'Rotina',types:['major','minor','pmin'],intro:'A técnica serve à música. Construa precisão com pouco esforço e use limitações criativas para desenvolver sua voz.',theory:[['Sincronia antes da velocidade','Mantenha movimentos pequenos, mão relaxada e som limpo. Abafe cordas que não estão sendo tocadas. Comece com uma nota por clique, depois duas. Se perder clareza, reduza o andamento. Pare e ajuste caso sinta dor.'],['O ritmo organiza o solo','Uma mesma sequência muda de caráter com o ritmo. Toque semínimas, colcheias e tercinas, sem alterar o BPM. Grave e confira se as notas estão alinhadas com os cliques. A tablatura aqui mostra alturas; a subdivisão é indicada em cada exercício.'],['Componha com restrições','Escolha três notas, uma região e um motivo rítmico. Repita e mude apenas o final. Acrescente pausas. Grave um minuto, ouça e identifique um ponto específico para melhorar na próxima sessão.']],application:'Sobre um acorde ou loop próprio, improvise por um minuto usando três notas. Repita o motivo duas vezes e transforme-o na terceira. Termine com uma nota longa.',drills:['Toque 1–2–3–4 em cada corda com palhetada alternada e sem tensão.','Pratique uma escala em colcheias por um minuto, com volume uniforme.','Grave uma improvisação e anote uma ideia boa e um ajuste concreto.'],goal:'Manter pulso, clareza e relaxamento e desenvolver um motivo reconhecível.'}
];
let saved;try{saved=JSON.parse(localStorage.getItem('atlas-v1')||'{}')}catch{saved={}}let state={view:'inicio',chapter:0,tab:'teoria',key:9,type:'major',pos:0,labels:'graus',...{}};const progress=saved.progress||{};function persist(){try{localStorage.setItem('atlas-v1',JSON.stringify(saved))}catch{}}function esc(s){return String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}const done=()=>Object.values(progress).filter(Boolean).length;
function nav(){ $('#chapters').innerHTML=chapters.map((c,i)=>'<button class="nav '+(state.view==='chapter'&&state.chapter===i?'active':'')+'" data-chapter="'+i+'"><span class="num">'+String(i+1).padStart(2,'0')+'</span><span>'+c.title+'</span></button>').join('');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',state.view===b.dataset.view));$('#side-progress').innerHTML='<div class="progress-track"><i style="width:'+done()/8*100+'%"></i></div><p>'+done()+' de 8 capítulos estudados</p>'}
const artwork='<svg viewBox="0 0 360 260" aria-hidden="true"><g transform="rotate(-25 180 130)"><rect x="153" y="-60" width="67" height="300" rx="2" fill="#52624e"/><rect x="160" y="-60" width="53" height="300" fill="#c5b58c"/>'+Array.from({length:12},(_,i)=>'<path d="M160 '+(i*26-30)+'h53" stroke="#eeecdd" stroke-width="3"/>').join('')+Array.from({length:6},(_,i)=>'<path d="M'+(164+i*9)+' -60v350" stroke="#55634f" stroke-width="'+(.5+i*.15)+'"/>').join('')+'<circle cx="187" cy="100" r="5" fill="#eef0df"/><circle cx="187" cy="179" r="5" fill="#eef0df"/></g><path d="M28 215Q70 150 115 198" fill="none" stroke="#8b9c7b" stroke-width="1"/><text x="25" y="239" fill="#75866b" font-size="10" letter-spacing="3">SEIS CORDAS. INFINITOS CAMINHOS.</text></svg>';
function originalHome(){ $('#crumb').textContent='Biblioteca / Seu livro de estudos';$('#main').innerHTML='<section class="hero"><div><span class="eyebrow">UM LIVRO ABERTO. UM NOVO CAMINHO.</span><h1>Seu próximo capítulo<br>começa nas cordas.</h1><p>Da primeira escala à liberdade de improvisar. Um espaço para explorar o braço, entender a música e cultivar sua prática, todos os dias.</p><div class="actions"><button class="btn primary" data-chapter="'+(saved.last||0)+'">'+(saved.last!==undefined?'Continuar estudando':'Abrir o primeiro capítulo')+' <span>↗</span></button><button class="btn" data-view="rotina">Minha rotina &nbsp; ◷</button></div></div><div class="hero-art">'+artwork+'</div></section><div class="stats"><div class="stat"><strong>08</strong><small>capítulos para explorar</small></div><div class="stat"><strong>19</strong><small>escalas e arpejos</small></div><div class="stat"><strong>'+done()+' / 8</strong><small>capítulos estudados</small></div></div><div class="section-head"><h2>Explore o seu livro</h2><input id="search" class="search" placeholder="⌕  Buscar um capítulo" aria-label="Buscar capítulo"></div><div class="grid" id="cards"></div><div class="banner"><div><span class="eyebrow">CONSTÂNCIA > VELOCIDADE</span><h3 style="margin-top:8px">Trinta minutos podem mudar o seu som.</h3><p>Uma rotina equilibrada entre técnica, repertório e criação.</p></div><button class="btn" data-view="rotina">Organizar minha prática ↗</button></div>';cards('')}
function originalCards(q){let found=chapters.map((c,i)=>({c,i})).filter(({c})=>(c.title+' '+c.short).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()));$('#cards').innerHTML=found.length?found.map(({c,i})=>'<button class="card" data-chapter="'+i+'"><div class="card-top"><span class="eyebrow">CAPÍTULO '+String(i+1).padStart(2,'0')+'</span><span class="badge">'+(progress[i]?'✓ Estudado':c.level)+'</span></div><h3>'+c.title+'</h3><p>'+c.short+'</p><div class="card-bottom"><span>Teoria · Shapes · Exercícios</span><span class="arrow">↗</span></div></button>').join(''):'<p class="empty muted">Nenhum capítulo encontrado.</p>'}
function openChapter(i){state.view='chapter';state.chapter=+i;state.tab='teoria';state.type=chapters[i].types[0];state.pos=0;saved.last=+i;persist();render();window.scrollTo(0,0)}
function originalChapter(){let c=chapters[state.chapter];$('#crumb').textContent='Livro / Capítulo '+(state.chapter+1);$('#main').innerHTML='<div class="chapter-title"><span class="eyebrow">CAPÍTULO '+String(state.chapter+1).padStart(2,'0')+' / '+c.level.toUpperCase()+'</span><h1>'+c.title+'</h1><p class="muted">'+c.intro+'</p></div><div class="tabs">'+[['teoria','01. Entender'],['shapes','02. Explorar'],['exercicios','03. Praticar']].map(([v,t])=>'<button class="tab '+(state.tab===v?'active':'')+'" data-tab="'+v+'">'+t+'</button>').join('')+'</div><section id="lesson"></section><div class="actions"><button class="btn '+(progress[state.chapter]?'':'primary')+'" id="complete">'+(progress[state.chapter]?'✓ Capítulo estudado · desfazer':'Marcar capítulo como estudado')+'</button>'+(state.chapter<7?'<button class="btn" data-chapter="'+(state.chapter+1)+'">Próximo capítulo →</button>':'')+'</div>';lesson()}
function originalLesson(){let c=chapters[state.chapter];if(state.tab==='teoria'){$('#lesson').innerHTML='<div class="theory">'+c.theory.map(([h,p],i)=>'<article class="panel"><span class="eyebrow">'+String(i+1).padStart(2,'0')+'</span><h3>'+h+'</h3><p>'+p+'</p></article>').join('')+'<div class="callout"><b>Leve para o instrumento</b><br>'+c.application+'</div><div class="panel"><h3>Como ler este livro</h3><p>Afinação padrão, da corda mais grave para a mais aguda: E–A–D–G–B–e. Na tablatura, a linha de cima é a corda mais aguda; os números são casas, 0 é corda solta e x é corda abafada. Leia da esquerda para a direita. Nos diagramas, a corda aguda também fica em cima. Os números dentro das notas representam graus, não dedos. T = tom; S = semitom; ♭ abaixa e ♯ eleva um semitom.</p></div>'+(state.chapter===3?caged():'')+'</div>';return}if(state.tab==='shapes'){lab();return}exercises()}
function caged(){return '<div class="panel"><h3>Um acorde, cinco formas: C maior</h3><p>Leia da 6ª para a 1ª corda. A tabela é de acordes simultâneos; os exercícios do laboratório são notas sucessivas.</p><div class="scroll-table"><table class="table"><tr><th>Forma</th><th>Casas E A D G B e</th><th>Tônicas de C</th></tr>'+[['C','x 3 2 0 1 0','5ª/3 e 2ª/1'],['A','x 3 5 5 5 3','5ª/3 e 3ª/5'],['G','8 7 5 5 5 8','6ª/8, 3ª/5 e 1ª/8'],['E','8 10 10 9 8 8','6ª/8, 4ª/10 e 1ª/8'],['D','x x 10 12 13 12','4ª/10 e 2ª/13']].map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</table></div><p class="muted">As formas G e C completas podem exigir grandes aberturas. Estude fragmentos sem forçar a mão. Para outro tom, desloque todas as casas pelo mesmo número de semitons e substitua cordas soltas por notas presas quando necessário.</p></div>'}
function params(){return '<div class="controls"><label>Tônica<select id="key">'+names.map((n,i)=>'<option value="'+i+'" '+(i===state.key?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>Escala / acorde<select id="type">'+chapters[state.chapter].types.map(t=>'<option value="'+t+'" '+(t===state.type?'selected':'')+'>'+scales[t].name+'</option>').join('')+'</select></label><label>Região<select id="pos">'+Array.from({length:5},(_,i)=>'<option value="'+i+'" '+(i===state.pos?'selected':'')+'>'+(state.type==='pmin'?'Box ':'Região ')+(i+1)+'</option>').join('')+'</select></label><label>Mostrar<select id="labels"><option value="graus" '+(state.labels==='graus'?'selected':'')+'>Graus</option><option value="notas" '+(state.labels==='notas'?'selected':'')+'>Notas</option></select></label></div>'}
const boxes=[[[0,3],[0,2],[0,2],[0,2],[0,3],[0,3]],[[3,5],[2,5],[2,5],[2,4],[3,5],[3,5]],[[5,7],[5,7],[5,7],[4,7],[5,8],[5,7]],[[7,10],[7,10],[7,9],[7,9],[8,10],[7,10]],[[10,12],[10,12],[9,12],[9,12],[10,12],[10,12]]];
function shape(){let scale=scales[state.type],base=(state.key-4+12)%12,notes=[];if(state.type==='pmin'){let shift=base;boxes[state.pos].forEach((arr,s)=>arr.forEach(f=>notes.push({s,f:f+shift,m:tuning[s]+f+shift})));return notes}let start=base+[-1,2,5,7,10][state.pos];start=Math.max(0,start);for(let s=0;s<6;s++)for(let f=start;f<=start+4;f++)if(scale.i.includes((tuning[s]+f-state.key+120)%12))notes.push({s,f,m:tuning[s]+f});return notes}
function spelling(){let s=scales[state.type];let letters=['C','D','E','F','G','A','B'],natural=[0,2,4,5,7,9,11],rootName=names[state.key],li=letters.indexOf(rootName[0]);return s.i.map((v,k)=>{let degree=+s.d[k].replace(/[^0-9]/g,''),idx=(li+degree-1)%7,delta=((state.key+v-natural[idx]+18)%12)-6;return letters[idx]+(delta>0?'♯'.repeat(delta):'♭'.repeat(-delta))})}
function originalDiagram(notes){let min=Math.min(...notes.map(n=>n.f)),max=Math.max(...notes.map(n=>n.f)),cols=max-min+1,w=760,h=240,x=60,step=(w-90)/cols,scale=scales[state.type],sp=spelling();let svg='<svg class="fret" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Diagrama de '+esc(names[state.key]+' '+scale.name)+' nas casas '+min+' a '+max+'">';for(let s=0;s<6;s++){let y=35+(5-s)*32;svg+='<text x="15" y="'+(y+4)+'" fill="#77816f" font-size="12">'+strings[s]+'</text><path d="M'+x+' '+y+'H'+(w-25)+'" stroke="#b5bcb1" stroke-width="'+(1+s*.16)+'"/>'}for(let j=0;j<=cols;j++)svg+='<path d="M'+(x+j*step)+' 25v180" stroke="#d5dacf"/>';for(let j=0;j<cols;j++)svg+='<text x="'+(x+(j+.5)*step)+'" y="226" text-anchor="middle" font-size="11" fill="#7b817b">'+(min+j)+'</text>';notes.forEach(n=>{let d=scale.i.indexOf((n.m-state.key+120)%12),xx=x+(n.f-min+.5)*step,yy=35+(5-n.s)*32;svg+='<g><circle cx="'+xx+'" cy="'+yy+'" r="12" fill="'+(d===0?'#be784c':'#345d48')+'"/><text x="'+xx+'" y="'+(yy+4)+'" text-anchor="middle" fill="white" font-size="10">'+(state.labels==='graus'?scale.d[d]:sp[d])+'</text></g>'});return svg+'</svg>'}
function tab(notes){return [5,4,3,2,1,0].map(s=>strings[s]+'|'+notes.map(n=>n.s===s?String(n.f).padStart(2,'-')+'-':'---').join('')+'|').join('\n')}
function ordered(){return shape().sort((a,b)=>a.m-b.m||a.s-b.s)}
function originalLab(){let s=scales[state.type],notes=shape();$('#lesson').innerHTML='<div class="panel"><span class="eyebrow">LABORATÓRIO DO BRAÇO</span><h2>'+names[state.key]+' · '+s.name+'</h2>'+params()+'<div class="formula">'+s.d.map((d,i)=>'<span class="pill">'+d+' · '+spelling()[i]+'</span>').join('')+'</div>'+(s.tone?'<p class="muted">Sequência de intervalos: '+s.tone+'</p>':'')+'<div class="fret-wrap">'+diagram(notes)+'</div><div class="legend"><span><i class="dot root"></i>Tônica</span><span><i class="dot"></i>Notas da escala</span></div><p class="muted">'+(state.type==='pmin'?'Box tradicional da pentatônica menor.':'Mapa de notas em uma janela de cinco casas; explore dedilhados confortáveis. Não é uma padronização de três notas por corda.')+' As regiões se sobrepõem. Em posições altas, o mapa pode exigir mais casas do que seu instrumento oferece.</p></div><div class="panel"><h3>Do desenho para a tablatura</h3><p>Escolha a direção e a subdivisão. Os saltos de duas posições pulam uma nota da coleção selecionada; em uma escala diatônica isso forma terças, mas em pentatônicas os intervalos variam.</p><pre>'+tab(ordered())+'</pre><div class="actions"><button class="btn primary" id="hear">▶ Ouvir escala</button><button class="btn" id="stop-audio">■ Parar</button></div><p class="muted">Áudio sintetizado de referência no BPM do metrônomo e na subdivisão escolhida.</p></div>'+(state.chapter===3?caged():'')}
function sequence(){let a=ordered(),out=[];for(let i=0;i<a.length-2;i++)out.push(a[i],a[i+1],a[i+2]);return out.slice(0,24)}
function originalExercises(){let c=chapters[state.chapter];$('#lesson').innerHTML='<div class="panel"><span class="eyebrow">PRÁTICA COM INTENÇÃO</span><h2>Três passos para fixar</h2>'+c.drills.map((d,i)=>'<label class="check"><input type="checkbox" data-check="'+state.chapter+'-'+i+'" '+(saved['check'+state.chapter+'-'+i]?'checked':'')+'><span><b>Exercício 0'+(i+1)+'</b><br>'+d+'</span></label>').join('')+'</div><div class="panel"><h3>Sequência aplicada · grupos de três</h3><p>Escolha o tom e a região. Toque três notas consecutivas, volte uma posição e repita. Comece em semínimas a 60 BPM; depois use colcheias, duas notas por clique. A tablatura mostra as primeiras 24 notas.</p>'+params()+'<pre>'+tab(sequence())+'</pre><button class="btn" id="hear-ex">▶ Ouvir sequência (semínimas)</button></div><div class="callout"><b>Antes de avançar</b><br>'+c.goal+' Repita três vezes com som limpo. Aumente 5 BPM quando estiver confortável.</div><div class="panel"><h3>Seu caderno</h3><p class="muted">Registre andamento, dificuldades e uma descoberta. Salvo automaticamente neste navegador.</p><textarea class="notes" id="chapter-notes" placeholder="Hoje pratiquei em… Meu próximo passo é…">'+esc(saved['notes'+state.chapter]||'')+'</textarea></div>'}
function routine(){ $('#crumb').textContent='Meu espaço / Minha rotina';let blocks=[['05','Aquecimento consciente','Movimentos leves, palhetada alternada e som limpo.'],['10','Escalas e conexões','Escolha um capítulo. Explore um shape e conecte à região vizinha.'],['05','Ritmo e articulação','Alterne semínimas e colcheias. Trabalhe abafamento e dinâmica.'],['10','Criação e escuta','Improvise, grave um minuto e anote uma descoberta.']];$('#main').innerHTML='<span class="eyebrow">UM ENCONTRO DIÁRIO COM O INSTRUMENTO</span><h1>Minha rotina.</h1><p class="muted">Trinta minutos de atenção valem mais que horas no piloto automático.</p><div class="two"><div class="panel"><h3>Sessão de 30 minutos</h3>'+blocks.map((b,i)=>'<div class="routine-row"><span class="routine-time">'+b[0]+'<small style="font-size:10px"> min</small></span><div><b>'+b[1]+'</b><p>'+b[2]+'</p></div><input type="checkbox" aria-label="Concluir '+b[1]+'" data-check="routine-'+i+'" '+(saved['checkroutine-'+i]?'checked':'')+'></div>').join('')+'<div class="actions"><button class="btn primary" id="log-session">Registrar sessão de hoje</button><button class="btn" id="reset-routine">Reiniciar checklist</button></div><p class="muted" id="session-status" aria-live="polite">'+(saved.sessions||[]).length+' sessões registradas.</p></div><div><div class="panel"><h3>Foco desta semana</h3><p class="muted">Defina uma meta que você consiga ouvir e medir.</p><textarea class="notes" id="week-notes" placeholder="Ex.: conectar dois boxes de A menor a 70 BPM, com som limpo.">'+esc(saved.week||'')+'</textarea></div><div class="callout"><b>Plano de sete dias</b><p>Seg · intervalos e escala maior<br>Ter · menor natural e relativas<br>Qua · pentatônicas e frases<br>Qui · CAGED e tríades<br>Sex · uma cor modal ou harmônica<br>Sáb · improvisação e gravação<br>Dom · escuta, revisão ou descanso</p></div></div></div><div class="panel"><h3>Diário de prática</h3><p class="muted">O registro usa a data local do seu dispositivo. Seus dados ficam neste navegador; use a exportação para guardar uma cópia.</p><div id="history">'+((saved.sessions||[]).slice().reverse().map(s=>'<p>'+esc(s.date)+' · '+esc(s.focus||'Sessão de guitarra')+'</p>').join('')||'<p class="muted">Seu primeiro registro começa hoje.</p>')+'</div><button class="btn" id="export">↓ Exportar meu caderno</button></div>'}
function render(){nav();if(state.view==='inicio')home();else if(state.view==='rotina')routine();else chapter()}
let audioCtx,scheduled=[],playTimer;function ctx(){return audioCtx||(audioCtx=new(window.AudioContext||window.webkitAudioContext)())}function tone(m,t,d=.35){let a=ctx(),o=a.createOscillator(),g=a.createGain();o.type='triangle';o.frequency.value=440*2**((m-69)/12);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.13,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g).connect(a.destination);o.start(t);o.stop(t+d+.02);scheduled.push(o)}function originalStop(){scheduled.forEach(o=>{try{o.stop()}catch{}});scheduled=[];clearTimeout(playTimer);document.querySelectorAll('#hear,#hear-ex').forEach(b=>b.disabled=false)}async function originalHear(notes){stop();let a=ctx();await a.resume();let step=60/bpm();notes.forEach((n,i)=>tone(n.m,a.currentTime+.08+i*step,Math.min(.5,step*.8)));document.querySelectorAll('#hear,#hear-ex').forEach(b=>b.disabled=true);playTimer=setTimeout(stop,(notes.length*step+.2)*1000)}function bpm(){let v=Math.max(30,Math.min(240,+$('#bpm').value||70));$('#bpm').value=v;return v}let metTimer,beat=0;async function toggleMet(){if(metTimer){clearInterval(metTimer);metTimer=null;$('#met-play').textContent='▶ Iniciar';$('.pulse').classList.remove('beat');return}await ctx().resume();const tick=()=>{let a=ctx(),o=a.createOscillator(),g=a.createGain();o.frequency.value=beat++%4===0?1300:850;g.gain.setValueAtTime(.15,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.035);o.connect(g).connect(a.destination);o.start();o.stop(a.currentTime+.04);$('.pulse').classList.add('beat');setTimeout(()=>$('.pulse').classList.remove('beat'),80)};beat=0;tick();metTimer=setInterval(tick,60000/bpm());$('#met-play').textContent='■ Parar'}
document.addEventListener('click',e=>{let b=e.target.closest('button,a');if(!b)return;if(b.dataset.chapter!==undefined){stop();openChapter(+b.dataset.chapter)}if(b.dataset.view){stop();state.view=b.dataset.view;render();window.scrollTo(0,0)}if(b.dataset.tab){stop();state.tab=b.dataset.tab;chapter()}if(b.id==='complete'){progress[state.chapter]=!progress[state.chapter];saved.progress=progress;persist();render()}if(b.id==='mobile')$('aside').classList.toggle('open');if(b.dataset.chapter!==undefined||b.dataset.view)$('aside').classList.remove('open');if(b.id==='hear')hear(getPattern());if(b.id==='hear-ex')hear(sequence(),1);if(b.id==='stop-audio')stop();if(b.id==='met-play')toggleMet();if(b.id==='minus'||b.id==='plus'){$('#bpm').value=bpm()+(b.id==='plus'?5:-5);bpm();if(metTimer){toggleMet();toggleMet()}}if(b.id==='reset-routine'){for(let i=0;i<4;i++)saved['checkroutine-'+i]=false;persist();routine()}if(b.id==='log-session'){saved.sessions=saved.sessions||[];let date=new Date().toLocaleDateString('pt-BR');saved.sessions.push({date,focus:saved.week||'Sessão de guitarra',completedBlocks:[0,1,2,3].filter(i=>saved['checkroutine-'+i]).length});persist();routine()}if(b.id==='export'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(saved,null,2)],{type:'application/json'}));a.download='atlas-meu-caderno.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)} });
document.addEventListener('change',e=>{let t=e.target;if(t.dataset.check){saved['check'+t.dataset.check]=t.checked;persist()}if(['key','type','pos','labels'].includes(t.id)){stop();state[t.id]=['key','pos'].includes(t.id)?+t.value:t.value;lesson()}if(t.id==='bpm'){bpm();if(metTimer){toggleMet();toggleMet()}}});document.addEventListener('input',e=>{let t=e.target;if(t.id==='search')cards(t.value);if(t.id==='chapter-notes'){saved['notes'+state.chapter]=t.value;persist()}if(t.id==='week-notes'){saved.week=t.value;persist()}});document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();stop();stopBacking();$('aside').classList.remove('open');state.view='inicio';render()});
const extraLessons=[
{focus:'Ouvir o tom antes de memorizar o desenho',time:'25–35 min',link:1,works:[['Campo harmônico maior','Em C maior, empilhe terças sobre cada nota: C, Dm, Em, F, G, Am, B°. A sequência de qualidades é maior–menor–menor–maior–maior–menor–diminuto. Se acrescentar sétimas: Cmaj7, Dm7, Em7, Fmaj7, G7, Am7, Bm7♭5.','Toque C–Am–F–G. Em cada troca, procure uma nota da tríade do acorde. Diga qual grau da escala ela representa.'],['A mesma coleção, outro centro','C–D–E–F–G–A–B forma C maior; A–B–C–D–E–F–G forma A menor natural. Compare os repousos: sobre C, E soa como 3ª; sobre Am, o mesmo E é a 5ª.','Sustente um C e termine uma frase em E. Depois sustente Am e termine em C. Ouça a função da nota, não só sua altura.']],mistake:'Tocar sempre da nota mais grave do shape pode esconder a tônica. Comece e termine em uma nota marcada em cobre.',advanced:[['Terças diatônicas','60 → 80 BPM','Toque 1–3, 2–4, 3–5, 4–6, 5–7, 6–1 e 7–2. Complete a oitava antes de voltar.','Semínimas; depois colcheias.'],['Ciclo de tonalidades','60 BPM','Transponha a mesma frase para C, G, D, A, E e B. Antes de tocar, encontre a nova tônica na 6ª ou 5ª corda.','Uma frase a cada quatro compassos.'],['Duas regiões, uma linha','70 BPM','Suba por uma região e desça pela vizinha. Faça a conexão por uma nota repetida, depois por slide.','Colcheias, sem acelerar na troca.']],phrase:[['Uma ideia, duas cores',[0,1,2,4,3,2,1,0]],['Chegada na terça',[0,1,3,2,1,0,1,2]]],quiz:{q:'Qual grau muda ao passar de A menor natural para A dórico?',answers:['A terça','A sexta','A quinta'],correct:1,why:'O dórico mantém a terça menor e eleva a ♭6 do eólio para 6 maior: F vira F♯ em A.'},chords:[[0,'maj'],[5,'maj'],[7,'dom'],[0,'maj']]},
{focus:'Conectar os boxes sem perder o fraseado',time:'30–40 min',link:6,works:[['Box 1 de A menor, corda por corda','6ª: 5–8; 5ª: 5–7; 4ª: 5–7; 3ª: 5–7; 2ª: 5–8; 1ª: 5–8. As tônicas A estão na 6ª/5, 4ª/7 e 1ª/5. Use o dedo 1 nas casas 5; ajuste os demais dedos ao intervalo.','Toque primeiro só as três tônicas. Acrescente C e E para formar a tríade menor. Por último, acrescente D e G.'],['Duas notas que mudam a cor','A menor pentatônica contém A–C–D–E–G. A maior pentatônica contém A–B–C♯–E–F♯. São escalas paralelas, com apenas A e E em comum. Não basta deslocar o nome da escala mantendo o mesmo centro.','Sobre A maior, compare C e C♯. No blues, essa fricção pode ser expressiva; em uma melodia diatônica, escolha conforme a harmonia.']],mistake:'Subir e descer boxes continuamente não desenvolve uma frase. Limite-se a três notas, faça pausas e repita uma ideia rítmica.',advanced:[['Pergunta e resposta','65 BPM','Faça dois compassos com três notas e responda nos dois seguintes. Mantenha o ritmo e mude apenas a última nota.','Quatro compassos em 4/4.'],['Conexão horizontal','70 BPM','Na 1ª corda, localize todas as notas da pentatônica entre as casas 5 e 17. Depois conecte-as a duas notas da 2ª corda.','Uma nota por clique.'],['Limitação criativa','75 BPM','Improvise sem tocar a corda 1. Na segunda rodada, use só cordas 1 e 2. Grave e compare o que mudou no fraseado.','Oito compassos por rodada.']],phrase:[['Pergunta pentatônica',[0,1,2,4,3,1,0,0]],['Resposta que respira',[4,3,2,1,2,4,1,0]]],quiz:{q:'Quais graus são retirados da escala maior para formar a pentatônica maior?',answers:['2 e 6','4 e 7','3 e 5'],correct:1,why:'A pentatônica maior usa 1–2–3–5–6; as notas 4 e 7 são retiradas.'},chords:[[0,'min7'],[0,'min7'],[5,'min7'],[0,'min7']]},
{focus:'Controlar tensão e resolução',time:'30–40 min',link:5,works:[['O dominante de um tom menor','Em A menor natural, o acorde do quinto grau é Em. Ao elevar G para G♯, a menor harmônica oferece E ou E7: E–G♯–B–D. A nota G♯ tende a subir para A; D tende a descer para C.','Toque G♯–A sobre E7–Am. Depois una D–C. Essas duas linhas explicam a resolução.'],['Maior com empréstimo do menor','Em C maior harmônica, a nota A♭ transforma F maior em F menor: F–A♭–C. O movimento Fm–C deixa A♭ descer para G enquanto C pode ficar como nota comum.','Alterne C–Fm–C. Faça uma melodia E–F–A♭–G–E para revelar a cor da escala.']],mistake:'A menor harmônica não precisa ocupar todo solo em tom menor. Use a sensível no momento do dominante e compare com a menor natural sobre o acorde de tônica.',advanced:[['Duas notas-guia','60 BPM','Em E7–Am, alterne G♯→A e D→C. Depois acrescente uma nota de passagem antes de cada chegada.','Dois compassos por acorde.'],['Segunda aumentada','55 BPM','Na menor harmônica, toque ♭6–7–1 em duas cordas. Procure um deslocamento confortável em vez de forçar uma abertura.','Semínimas com som igual.'],['Comparação paralela','65 BPM','Toque a mesma frase em maior natural e maior harmônica, mudando 6 para ♭6. Grave as duas versões.','Quatro compassos por versão.']],phrase:[['A sensível pede repouso',[0,2,4,5,6,7,6,7]],['A cor da sexta menor',[4,5,4,2,3,2,1,0]]],quiz:{q:'Na menor harmônica, qual alteração cria a sensível?',answers:['♭3 vira 3','♭6 vira 6','♭7 vira 7'],correct:2,why:'A sétima da menor natural é elevada em um semitom. Em A menor, G vira G♯.'},chords:[[5,'min'],[7,'dom'],[0,'min'],[0,'min']]},
{focus:'Unir acorde, arpejo e escala na mesma região',time:'30–45 min',link:5,works:[['C maior na forma de A','Use x–3–5–5–5–3, da 6ª para a 1ª corda. As alturas são C–G–C–E–G. A tônica está na 5ª/3 e na 3ª/5. Toque o acorde, depois arpeje e por último improvise perto dele.','Nas cordas 3, 2 e 1, toque 5–5–3 como um pequeno acorde. As notas são C–E–G: uma tríade em posição fundamental.'],['C maior na forma de E','Use 8–10–10–9–8–8. Nas três cordas agudas, 9–8–8 oferece E–G–C: primeira inversão da tríade. Compare com C–E–G da forma anterior.','Ligue as duas tríades com movimentos pequenos. Diga os nomes das notas para não confundir forma com tonalidade.']],mistake:'CAGED é um mapa de acordes. As cinco janelas de escala do laboratório são uma exploração complementar, não uma correspondência rígida entre cada número e uma letra.',advanced:[['Cadeia de tônicas','60 BPM','Encontre C nas formas C, A, G, E e D. Toque apenas tônicas e visualize o contorno do acorde ao redor.','Quatro cliques por região.'],['Fragmentos de tríade','65 BPM','Toque C maior em três cordas. Mova para a inversão mais próxima e mantenha a mesma dinâmica.','Semínimas.'],['Acorde vira melodia','70 BPM','Toque o acorde por um compasso; responda com uma frase de escala no seguinte. Termine em 1, 3 ou 5.','Dois compassos por forma.']],phrase:[['Contorno da tríade',[0,1,2,3,2,1,0,0]],['Conexão entre vozes',[2,3,4,3,2,1,2,0]]],quiz:{q:'Uma forma de E maior deslocada três casas por pestana produz qual acorde?',answers:['G maior','A maior','C maior'],correct:0,why:'E sobe três semitons: F, F♯, G. A forma continua sendo de E; o acorde passa a ser G.'},chords:[[0,'maj'],[5,'maj'],[7,'maj'],[0,'maj']]},
{focus:'Ouvir uma cor sobre um centro estável',time:'35–45 min',link:2,works:[['D dórico e D eólio','D dórico: D–E–F–G–A–B–C. D eólio: D–E–F–G–A–B♭–C. O único grau alterado é 6. Sobre Dm7 sustentado, B soa como 6 maior; B♭ entrega a cor da menor natural.','Faça D–F–A–B–A–F–D. Repita com B♭ e compare a sensação. Mantenha D no baixo.'],['C lídio e C jônio','C lídio contém F♯; C jônio contém F. Compare a tensão de ♯4 com a de 4 sobre Cmaj7. Resolva F♯ em G para ouvir um caminho característico.','Use C–E–F♯–G–E sobre um pedal de C. Troque F♯ por F e ouça o contraste sem mudar o acorde.']],mistake:'Começar uma escala maior a partir de outra nota não garante um som modal. O acompanhamento e os repousos precisam estabelecer a nova tônica.',advanced:[['Um grau por vez','60 BPM','Compare dórico/eólio, lídio/jônio e mixolídio/jônio na mesma tônica. Toque só o grau que muda e uma tônica.','Quatro cliques por nota.'],['Pedal e cor','65 BPM','Sobre o pedal, faça uma frase com a tônica, a terça e o grau característico do modo selecionado.','Dois compassos, com pausas.'],['Escuta sem desenho','Livre','Cante uma frase modal antes de procurar no braço. Grave e veja se o centro continua claro quando você para de tocar.','Três tentativas por modo.']],phrase:[['A cor do modo',[0,2,4,5,4,2,1,0]],['Tensão e repouso',[0,3,4,6,5,3,2,0]]],quiz:{q:'Qual nota caracteriza C lídio em comparação com C maior?',answers:['B♭','F♯','E♭'],correct:1,why:'O lídio tem ♯4. Em C, o quarto grau F é elevado a F♯.'},chords:[[0,'pedal'],[0,'pedal'],[0,'pedal'],[0,'pedal']]},
{focus:'Acompanhar a harmonia com notas-alvo',time:'30–45 min',link:3,works:[['Três inversões de C maior','Nas cordas G–B–e: 5–5–3 = C–E–G; 9–8–8 = E–G–C; 12–13–12 = G–C–E. Em cada caso, a nota mais grave define a inversão.','Toque cada tríade como bloco e depois como arpejo. Cante a nota mais grave de cada forma.'],['A força das notas-guia','Em Dm7–G7–Cmaj7, as terças e sétimas são F/C, B/F e E/B. A linha C→B pode conectar ii a V; F→E resolve V em I.','Grave os acordes lentamente. Toque uma nota longa por acorde, buscando o menor deslocamento até a nota-alvo seguinte.']],mistake:'Tocar um arpejo inteiro em toda troca pode deixar o solo mecânico. Escolha uma nota-alvo e aproxime-se dela com uma ideia rítmica.',advanced:[['Terças em evidência','60 BPM','Toque a terça de cada acorde de uma progressão. Depois acrescente a tônica antes dela.','Um compasso por acorde.'],['Sétimas conectadas','65 BPM','Compare maj7, m7 e 7 na mesma tônica. Identifique qual nota mudou em cada passagem.','Uma nota por clique.'],['Condução de vozes','70 BPM','Ligue duas tríades em cordas vizinhas, movendo cada voz para a nota mais próxima. Evite saltar para a forma conhecida.','Dois tempos por acorde.']],phrase:[['Arpejo em espelho',[0,1,2,3,4,3,2,0]],['Salto e retorno',[0,2,1,3,2,4,1,0]]],quiz:{q:'Qual é a diferença entre Cmaj7 e C7?',answers:['A terça','A quinta','A sétima'],correct:2,why:'Cmaj7 tem B, a 7 maior. C7 tem B♭, a ♭7. Ambos contêm a tríade C–E–G.'},chords:[[2,'min7'],[7,'dom'],[0,'maj7'],[0,'maj7']]},
{focus:'Dar intenção e afinação a cada nota',time:'30–40 min',link:1,works:[['Blue note como passagem','Em A blues menor: A–C–D–E♭–E–G. A passagem D–E♭–E cria tensão e chegada. A nota E♭ também pode ser pensada enarmonicamente como D♯ quando sobe para E.','Toque 7–8–9 na corda G: D–E♭–E. Repita com palhetas, slide e ligado. Ouça a mesma passagem com articulações diferentes.'],['Bend com destino','Na corda B, casa 8 é G e casa 10 é A. Toque A na casa 10 como referência. Volte à casa 8 e faça um bend de um tom para chegar à mesma altura.','Compare o bend com a nota de destino, sem pressa. Solte o bend de forma controlada; abafe a corda antes de reposicionar a mão.']],mistake:'Mais força não significa melhor bend. Use apoio e busque a altura certa. Dor é um sinal para parar e ajustar o gesto.',advanced:[['Afinação do bend','60 BPM','Alterne nota-alvo e bend. Faça cinco repetições e avalie se a chegada está baixa, alta ou afinada.','Duas pulsações para subir e duas para sustentar.'],['Vibrato com pulso','65 BPM','Sustente uma nota e faça oscilações pequenas e regulares. Compare duas e três oscilações por clique.','Volume uniforme.'],['Doze compassos','70 BPM','Crie uma frase nos quatro primeiros compassos, varie sobre IV e responda no retorno a I. Deixe espaço antes do V.','Um chorus completo.']],phrase:[['Passagem pela blue note',[0,1,2,3,4,2,1,0]],['Pergunta e retorno',[4,5,4,3,2,1,2,0]]],quiz:{q:'Qual nota a escala blues menor acrescenta à pentatônica menor?',answers:['♭5','7 maior','2 maior'],correct:0,why:'A fórmula é 1–♭3–4–♭5–5–♭7. A ♭5 é a blue note acrescentada.'},chords:[[0,'dom'],[5,'dom'],[0,'dom'],[7,'dom']]},
{focus:'Ganhar controle e desenvolver ideias próprias',time:'25–40 min',link:0,works:[['Velocidade medida com clareza','A 60 BPM, semínimas produzem uma nota por segundo; colcheias, duas; semicolcheias, quatro. Antes de aumentar o metrônomo, mude a subdivisão e mantenha o mesmo relaxamento.','Toque oito semínimas, dezesseis colcheias e oito semínimas de novo. O pulso não muda, só a densidade das notas.'],['Um motivo, três transformações','Escolha três notas e um ritmo. Variação 1: repita com outro final. Variação 2: comece em outro tempo. Variação 3: toque em outra oitava. A identidade deve continuar reconhecível.','Grave quatro compassos. Escute sem tocar e marque o momento em que a ideia ficou mais clara. Use isso como ponto de partida da próxima sessão.']],mistake:'O metrônomo mede regularidade, não valor musical. Se o som perder clareza ou houver tensão, volte ao andamento em que você consegue ouvir e controlar cada nota.',advanced:[['Troca de subdivisão','60 BPM','Alterne um compasso de semínimas, um de colcheias e um de tercinas. Conte em voz alta antes de tocar.','Mantenha o clique em semínimas.'],['Acentos móveis','65 BPM','Toque colcheias em grupos de quatro. Acentue primeiro a nota 1, depois 2, 3 e 4, mantendo as demais suaves.','Quatro compassos por acento.'],['Solo com começo, meio e fim','70 BPM','Comece com poucas notas, aumente a atividade no meio e termine com uma frase curta. Não use velocidade como único recurso.','Oito compassos gravados.']],phrase:[['Motivo repetido',[0,1,2,0,0,1,2,4]],['Variação do final',[0,1,2,4,3,2,1,0]]],quiz:{q:'A 60 BPM, quantas colcheias cabem em cada clique de semínima?',answers:['Uma','Duas','Quatro'],correct:1,why:'Uma semínima se divide em duas colcheias. O metrônomo continua a 60 BPM.'},chords:[[0,'min7'],[5,'min7'],[7,'min7'],[0,'min7']]}
];
const symbols=['1 2 3','1 ♭3 5','♭6 7','C A G E D','♯4','1 3 5 7','♭5','♪ ♫'];
function chapterPreview(i){let specs=[{name:'C maior',type:'major',key:0,min:7,max:10,detail:'Escala natural'},{name:'A pentatônica menor',type:'pmin',key:9,min:5,max:8,detail:'Box 1'},{name:'A menor harmônica',type:'hmin',key:9,min:5,max:9,detail:'7ª maior em destaque'},{name:'C maior · forma de E',type:'tri',key:0,min:8,max:10,detail:'Acorde CAGED'},{name:'C lídio',type:'lyd',key:0,min:7,max:10,detail:'Cor modal: ♯4'},{name:'Cmaj7',type:'maj7',key:0,min:7,max:10,detail:'Arpejo: 1–3–5–7'},{name:'A blues menor',type:'blues',key:9,min:5,max:8,detail:'Blue note: ♭5'},{name:'Cromático 1–2–3–4',type:null,key:0,min:1,max:4,detail:'Coordenação · dedos 1 a 4'}];let p=specs[i],notes=[];if(i===3){[8,10,10,9,8,8].forEach((f,s)=>notes.push({s,f,m:tuning[s]+f}));}else if(i===1){boxes[0].forEach((a,s)=>a.forEach(f=>notes.push({s,f:f+5,m:tuning[s]+f+5})));}else{for(let s=0;s<6;s++)for(let f=p.min;f<=p.max;f++)if(!p.type||scales[p.type].i.includes((tuning[s]+f-p.key+120)%12))notes.push({s,f,m:tuning[s]+f});}return {...p,notes}}
function miniArt(i){let p=chapterPreview(i),scale=p.type?scales[p.type]:null,x=38,step=300/(p.max-p.min+1),v='<div class="mini-caption"><strong>'+p.name+'</strong><span>CASAS '+p.min+'–'+p.max+'</span></div><svg viewBox="0 0 360 130" role="img" aria-label="'+p.name+', '+p.detail+', casas '+p.min+' a '+p.max+'"><title>'+p.name+' · '+p.detail+'</title>';for(let s=0;s<6;s++){let y=19+(5-s)*15;v+='<text x="17" y="'+(y+3)+'" text-anchor="middle" class="mini-string">'+strings[s]+'</text><path d="M'+x+' '+y+'H338" class="mini-string-line" stroke-width="'+(.65+(5-s)*.12)+'"/>';}for(let f=p.min;f<=p.max+1;f++){let xx=x+(f-p.min)*step;v+='<path d="M'+xx+' 12v89" class="mini-fret"/>';if(f<=p.max)v+='<text x="'+(xx+step/2)+'" y="118" text-anchor="middle" class="mini-fret-number">'+f+'</text>';}p.notes.forEach(n=>{let idx=scale?scale.i.indexOf((n.m-p.key+120)%12):-1,degree=scale?scale.d[idx]:String(n.f),isRoot=!!scale&&idx===0,color=isRoot?'var(--copper)':'var(--green)',isColor=(i===2&&degree==='7')||(i===4&&degree==='♯4')||(i===6&&degree==='♭5'),xx=x+(n.f-p.min+.5)*step,yy=19+(5-n.s)*15;v+='<g><circle cx="'+xx+'" cy="'+yy+'" r="6.3" fill="'+color+'" '+(isColor?'stroke="var(--copper)" stroke-width="2.4"':'')+'/>'+'<text x="'+xx+'" y="'+(yy+2.5)+'" text-anchor="middle" class="mini-degree">'+degree+'</text></g>'});return v+'</svg><div class="mini-foot"><span>'+p.detail+'</span><span>'+(p.type?'● Tônica em cobre':'Números = dedos')+'</span></div>'}
function coverArt(){let s='<svg viewBox="0 0 440 390" aria-hidden="true"><defs><linearGradient id="wood" x2="1" y2="0"><stop stop-color="#827052"/><stop offset=".45" stop-color="#ad966e"/><stop offset="1" stop-color="#756047"/></linearGradient></defs><circle cx="235" cy="195" r="155" fill="none" stroke="#b3b58c" opacity=".15"/><circle cx="235" cy="195" r="125" fill="none" stroke="#b3b58c" opacity=".1"/><g transform="translate(105,-50) rotate(26 140 220)"><rect x="83" y="-80" width="116" height="620" fill="#14271f"/><rect x="89" y="-80" width="104" height="620" fill="url(#wood)"/>';for(let j=0;j<14;j++)s+='<path d="M89 '+(j*35-50)+'h104" stroke="#e8d7ac" stroke-width="3" opacity=".7"/>';for(let k=0;k<6;k++)s+='<path d="M'+(98+k*17)+' -80v620" stroke="#eee5cf" opacity="'+(.6+k*.06)+'" stroke-width="'+(.7+k*.25)+'"/>';[55,125,195,300].forEach(y=>s+='<circle cx="141" cy="'+y+'" r="5" fill="#e9debf" opacity=".85"/>');s+='<circle cx="98" cy="265" r="13" fill="#c48655"/><text x="98" y="269" text-anchor="middle" fill="#fff6e2" font-size="10" font-family="monospace">1</text><circle cx="166" cy="265" r="12" fill="#c7d0ad"/><text x="166" y="269" text-anchor="middle" fill="#304434" font-size="9" font-family="monospace">♭3</text><circle cx="132" cy="230" r="12" fill="#c7d0ad"/><text x="132" y="234" text-anchor="middle" fill="#304434" font-size="10" font-family="monospace">5</text></g><path d="M42 312h80M42 312v-45" stroke="#b6bb94" stroke-width="1" opacity=".5"/><text x="44" y="331" fill="#b6bb94" font-size="8" font-family="monospace" letter-spacing="2">EXPLORE O BRAÇO</text></svg>';return s}
function home(){ $('#crumb').textContent='Seu espaço / Caderno de estúdio';let sessions=(saved.sessions||[]).length;$('#main').innerHTML='<div class="home-intro"><div><span class="eyebrow">BEM-VINDO AO SEU ESTÚDIO</span><h1>Entre notas e descobertas.</h1><p>Abra o livro. Encontre uma ideia. Transforme em som.</p></div><div class="edition">ATLAS / VOL. 01<br>CADERNO DE ESTÚDIO<br>EDIÇÃO EXPANDIDA</div></div><section class="cover"><div class="cover-copy"><span class="eyebrow">LIVRO DE GUITARRA</span><h1>Seu espaço de estudo.</h1><p>Retome um capítulo ou prepare sua próxima sessão de prática.</p><div class="actions"><button class="btn primary" data-chapter="'+(saved.last||0)+'">'+(saved.last!==undefined?'Retomar capítulo '+String(saved.last+1).padStart(2,'0'):'Começar a explorar')+' ↗</button><button class="btn secondary" data-view="rotina">Minha prática ◷</button></div></div><div class="cover-art">'+coverArt()+'<span class="cover-stamp">◉ &nbsp; ESTUDE. OUÇA. CRIE.</span><span class="cover-bottom">DA TEORIA AO SOM / SEM ATALHOS, COM DIREÇÃO.</span></div></section><div class="stats"><div class="stat"><strong>08</strong><small>capítulos<br>conectados</small></div><div class="stat"><strong>19</strong><small>escalas<br>e arpejos</small></div><div class="stat"><strong>'+done()+'<span style="font-size:14px;color:var(--muted)">/8</span></strong><small>capítulos<br>estudados</small></div><div class="stat"><strong>'+String(sessions).padStart(2,'0')+'</strong><small>sessões<br>registradas</small></div></div><div class="section-head"><div><span class="eyebrow">O CONHECIMENTO TEM CAMINHOS</span><h2>Escolha o próximo capítulo.</h2></div><input id="search" class="search" placeholder="⌕  Escalas, modos, acordes…" aria-label="Buscar capítulo"></div><div class="grid" id="cards"></div><div class="home-bottom"><div class="panel"><span class="eyebrow">UMA BOA ORDEM PARA COMEÇAR</span><h3>Do mapa à liberdade.</h3>'+[['01','Entenda os intervalos','Cap. 1'],['02','Explore e conecte shapes','Cap. 2 e 4'],['03','Ouça as cores da harmonia','Cap. 3, 5 e 6'],['04','Conte uma história com notas','Cap. 7 e 8']].map(r=>'<div class="path-step"><strong>'+r[0]+'</strong>'+r[1]+'<span>'+r[2]+'</span></div>').join('')+'</div><div class="panel"><span class="eyebrow">LEMBRETE DO ESTÚDIO</span><p class="daily-quote">“Antes de tocar mais rápido, encontre algo que valha a pena repetir.”</p><p class="muted">Hoje, escolha uma frase de quatro notas. Toque, cante, deixe um silêncio. A música também acontece no espaço.</p><button class="btn" data-chapter="7">Trabalhar meu fraseado ↗</button></div></div><div class="banner"><div><span class="eyebrow">SUA PRÓXIMA SESSÃO</span><h3 style="margin-top:8px">Um pouco de estudo. Muito mais música.</h3><p>Prepare 30 minutos com técnica, exploração e criação.</p></div><button class="btn" data-view="rotina">Abrir minha rotina ↗</button></div><div class="section-head"><div><span class="eyebrow">SEMPRE À MÃO</span><h2>Pequeno dicionário do braço.</h2></div></div><div class="glossary">'+[['Tônica','A nota que funciona como centro e ponto de repouso.'],['Grau','A posição de uma nota em relação à tônica: 1, 2, 3…'],['Intervalo','A distância entre duas notas; um semitom equivale a uma casa.'],['Shape','Uma disposição de notas no braço; não define sozinho o som.'],['Arpejo','As notas de um acorde tocadas em sequência.'],['Motivo','Uma ideia melódica ou rítmica curta que você desenvolve.']].map(([a,b])=>'<div><b>'+a+'</b><p>'+b+'</p></div>').join('')+'</div>';cards('')}
function cards(q){let normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();let found=chapters.map((c,i)=>({c,i})).filter(({c})=>normalize(c.title+' '+c.short).includes(normalize(q)));$('#cards').innerHTML=found.length?found.map(({c,i})=>'<button class="card" data-chapter="'+i+'"><div class="card-graphic" data-symbol="'+symbols[i]+'">'+miniArt(i)+'</div><div class="card-content"><div class="card-top"><span class="eyebrow">CAPÍTULO '+String(i+1).padStart(2,'0')+'</span><span class="badge">'+(progress[i]?'✓ ESTUDADO':c.level.toUpperCase())+'</span></div><h3>'+c.title+'</h3><p>'+c.short+'</p><div class="card-bottom"><span>4 SEÇÕES · '+extraLessons[i].time.toUpperCase()+'</span><span class="arrow">↗</span></div></div></button>').join(''):'<p class="empty muted">Nenhum capítulo encontrado. Tente outro tema.</p>'}
function chapter(){let c=chapters[state.chapter],x=extraLessons[state.chapter];$('#crumb').textContent='Caderno / Capítulo '+String(state.chapter+1).padStart(2,'0');$('#main').innerHTML='<div class="chapter-title" data-number="'+String(state.chapter+1).padStart(2,'0')+'"><div class="notebook-heading"><span class="eyebrow">CAPÍTULO '+String(state.chapter+1).padStart(2,'0')+' / '+c.level.toUpperCase()+'</span><button class="chapter-fav '+(saved['fav'+state.chapter]?'selected':'')+'" id="favorite">'+(saved['fav'+state.chapter]?'★ Favorito':'☆ Favoritar')+'</button></div><h1>'+c.title+'</h1><p class="muted">'+c.intro+'</p><div class="chapter-meta"><span>◷ '+x.time+'</span><span>◫ 4 seções de estudo</span><span>♫ Ouça e pratique</span></div></div><div class="tabs">'+[['teoria','01. Fundamentos'],['shapes','02. Mapa do braço'],['exercicios','03. Prática guiada'],['musica','04. Fazer música']].map(([v,t])=>'<button class="tab '+(state.tab===v?'active':'')+'" data-tab="'+v+'">'+t+'</button>').join('')+'</div><section id="lesson"></section><div class="actions"><button class="btn '+(progress[state.chapter]?'':'primary')+'" id="complete">'+(progress[state.chapter]?'✓ Capítulo estudado · desfazer':'Marcar capítulo como estudado')+'</button>'+(state.chapter<7?'<button class="btn" data-chapter="'+(state.chapter+1)+'">Próximo capítulo →</button>':'')+'</div>';lesson()}
function lesson(){if(state.tab==='musica'){music();return}originalLesson();if(state.tab==='teoria'){let x=extraLessons[state.chapter];$('.theory').insertAdjacentHTML('beforeend','<section class="deep-content"><span class="eyebrow">ENTENDA NO INSTRUMENTO</span><h2>Da ideia para a prática.</h2><div class="worked-grid">'+x.works.map((w,i)=>'<article class="panel worked"><span class="example-no">ESTUDO DE CASO 0'+(i+1)+'</span><h3>'+w[0]+'</h3><p>'+w[1]+'</p><div class="reading-note"><b>↗</b><p>'+w[2]+'</p></div></article>').join('')+'</div><div class="callout"><b>Um erro comum</b><br>'+x.mistake+'</div>'+connection()+'</section>')}}
function connection(){let x=extraLessons[state.chapter];return '<div class="practice-route"><b>↗</b><p><span class="eyebrow">CONTINUE CONECTANDO AS IDEIAS</span><br>Este estudo conversa com <strong>'+chapters[x.link].title.toLowerCase()+'</strong>.</p><button class="btn" data-chapter="'+x.link+'">Abrir capítulo '+(x.link+1)+'</button></div>'}
function diagram(notes){let svg=originalDiagram(notes).replace('role="img"','role="group"'),idx=0;return svg.replace(/<g>/g,()=>{let n=notes[idx++],d=scales[state.type].i.indexOf((n.m-state.key+120)%12);return '<g class="fret-note '+(d===0?'is-root':'')+'" data-midi="'+n.m+'" data-string="'+n.s+'" data-fret="'+n.f+'" role="button" tabindex="0" aria-label="'+spelling()[d]+', grau '+scales[state.type].d[d]+', corda '+strings[n.s]+', casa '+n.f+'">'})}
state.pattern='asc';state.speed=1;let animationTimers=[];
function getPattern(){let a=ordered();if(state.pattern==='desc')return a.reverse();if(state.pattern==='round')return a.concat(a.slice(0,-1).reverse());if(state.pattern==='thirds'){let r=[];for(let i=0;i<a.length-2;i++)r.push(a[i],a[i+2]);return r}if(state.pattern==='four'){let r=[];for(let i=0;i<a.length-3;i++)r.push(...a.slice(i,i+4));return r}return a}
function lab(){originalLab();let p=$('#lesson .panel');p.querySelector('h2').insertAdjacentHTML('afterend','<p class="muted">Clique em qualquer nota para ouvi-la. Use as tônicas em cobre como pontos de orientação.</p>');let pre=$('#lesson pre');pre.textContent=tab(getPattern());pre.insertAdjacentHTML('beforebegin','<div class="transport"><label>Padrão<select id="pattern">'+[['asc','Ascendente'],['desc','Descendente'],['round','Subir e descer'],['thirds','Saltos de duas posições'],['four','Grupos de quatro']].map(([v,t])=>'<option value="'+v+'" '+(state.pattern===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Notas por clique<select id="speed">'+[[1,'1 · semínimas'],[2,'2 · colcheias'],[3,'3 · tercinas'],[4,'4 · semicolcheias']].map(([v,t])=>'<option value="'+v+'" '+(state.speed===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label></div>');$('#hear').textContent='▶ Ouvir padrão';$('#lesson .panel:last-of-type').insertAdjacentHTML('beforeend','<div class="audio-status" id="play-status" aria-live="polite"></div><p class="tab-note">ALTURAS EM SEQUÊNCIA · RITMO DEFINIDO PELA SUBDIVISÃO ESCOLHIDA</p>');$('#lesson').insertAdjacentHTML('beforeend','<div class="reading-note"><b>♪</b><p><strong>Como estudar o mapa</strong><br>1. Encontre e toque todas as tônicas. 2. Toque apenas 1, 3 (ou ♭3) e 5. 3. Acrescente as outras notas. 4. Crie uma frase curta sem começar pela nota mais grave.</p></div>')}
function exercises(){originalExercises();let x=extraLessons[state.chapter];$('#lesson').insertAdjacentHTML('beforeend','<div class="section-head"><div><span class="eyebrow">APROFUNDE O ESTUDO</span><h2>Mais intenção a cada repetição.</h2></div></div>'+x.advanced.map((d,i)=>'<article class="panel practice-card"><div class="exercise-level"><span>DESAFIO 0'+(i+1)+' / '+['CONSTRUIR','CONECTAR','CRIAR'][i]+'</span><span>'+d[1]+'</span></div><h3>'+d[0]+'</h3><p>'+d[2]+'</p><p class="tab-note">'+d[3]+'</p><label class="check"><input type="checkbox" data-check="deep-'+state.chapter+'-'+i+'" '+(saved['checkdeep-'+state.chapter+'-'+i]?'checked':'')+'><span>Consigo repetir com clareza e sem tensão.</span></label></article>').join('')+connection())}
let phraseIndex=0;function phraseNotes(){let a=ordered(),rootIndex=a.findIndex(n=>(n.m-state.key+120)%12===0);rootIndex=Math.max(0,rootIndex);return extraLessons[state.chapter].phrase[phraseIndex][1].map(i=>a[Math.min(rootIndex+i,a.length-1)])}
function chordName(offset,quality){return names[(state.key+offset)%12]+({maj:'',min:'m',min7:'m7',maj7:'maj7',dom:'7',pedal:' · pedal'}[quality]||'')}
function music(){let x=extraLessons[state.chapter];phraseIndex=Math.min(phraseIndex,1);$('#lesson').innerHTML='<div class="callout"><b>O objetivo musical</b><br>'+x.focus+'. Nesta seção, o tom e a escala selecionados atualizam as frases e o acompanhamento.</div>'+params()+'<div class="studio-grid"><section class="panel full-width"><span class="eyebrow">VOCABULÁRIO EM CONSTRUÇÃO</span><h2>Uma frase. Muitas possibilidades.</h2><div class="phrase-tabs">'+x.phrase.map((p,i)=>'<button class="phrase-choice '+(i===phraseIndex?'active':'')+'" data-phrase="'+i+'">0'+(i+1)+' · '+p[0]+'</button>').join('')+'</div><p>Exemplo original no tom selecionado. Toque as oito notas em colcheias: um compasso de 4/4. Depois repita com uma pausa de um compasso. A numeração da tablatura indica casas; ela não escreve a duração das notas.</p><pre>'+tab(phraseNotes())+'</pre><div class="actions"><button class="btn primary" id="hear-phrase">▶ Ouvir frase</button><button class="btn" id="stop-audio">■ Parar</button></div><div class="audio-status" id="play-status" aria-live="polite"></div><div class="reading-note"><b>↻</b><p>Primeiro copie a frase. Depois mude a última nota. Na terceira rodada, mantenha as notas e invente outro ritmo. Termine cantando sua versão antes de tocá-la.</p></div></section><section class="panel"><span class="eyebrow">UM CHÃO PARA SUAS IDEIAS</span><h3>Acompanhamento de estudo</h3><p>Um acorde por compasso de 4/4, no BPM do metrônomo. O pedal usa só a tônica em duas oitavas para você explorar diferentes modos.</p><div class="chord-row">'+x.chords.map(([o,q],i)=>'<div class="chord-tile" data-chord-tile="'+i+'"><strong>'+chordName(o,q)+'</strong><span>COMPASSO '+(i+1)+'</span></div>').join('')+'</div><div class="actions"><button class="btn primary" id="backing-play">▶ Tocar acompanhamento</button><button class="btn" id="backing-stop">■ Parar</button></div><div class="audio-status" id="backing-status" aria-live="polite"></div><p class="muted">Timbre sintetizado. O acompanhamento usa a tônica escolhida e a harmonia proposta no capítulo. Se trocar para uma escala de outra qualidade, ouça as tensões e consulte os fundamentos.</p></section><section class="panel"><span class="eyebrow">CONFIRA SUA COMPREENSÃO</span><h3>Pense antes de olhar.</h3><p>'+x.quiz.q+'</p><div class="quiz-answers">'+x.quiz.answers.map((a,i)=>'<button class="btn" data-answer="'+i+'">'+a+'</button>').join('')+'</div><div class="quiz-feedback" id="quiz-result" aria-live="polite"></div><div class="reading-note"><b>?</b><p>Tente explicar sua resposta em voz alta. Se conseguir demonstrar no braço, a ideia está começando a fazer parte do seu vocabulário.</p></div></section><section class="panel full-width"><span class="eyebrow">TREINE A ESCUTA</span><h3>Maior ou menor?</h3><p>Ouça uma tríade arpejada e depois em bloco. Identifique sua qualidade pela terça. A tônica é sorteada a cada rodada.</p><div class="actions"><button class="btn primary" id="ear-new">♫ Sortear e ouvir</button><button class="btn" id="ear-repeat">↻ Repetir</button><button class="btn" data-ear="maj">Maior</button><button class="btn" data-ear="min">Menor</button></div><div class="quiz-feedback" id="ear-result" aria-live="polite"></div></section></div>'+connection()}
let earQuestion=null;async function earPlay(fresh=false){if(fresh||!earQuestion)earQuestion={key:Math.floor(Math.random()*12),quality:Math.random()>.5?'maj':'min'};let a=ctx();await a.resume();stop();let intervals=earQuestion.quality==='maj'?[0,4,7]:[0,3,7];let midi=48+earQuestion.key;intervals.forEach((n,i)=>tone(midi+n,a.currentTime+.1+i*.5,.4));intervals.forEach(n=>tone(midi+n,a.currentTime+1.9,1));$('#ear-result').textContent='Ouça a relação entre a tônica e a terça.'}
let backingTimer=null,backingOsc=[],backingBeat=0;function stopBacking(){clearInterval(backingTimer);backingTimer=null;backingOsc.forEach(o=>{try{o.stop()}catch{}});backingOsc=[];if($('#backing-status'))$('#backing-status').textContent='Acompanhamento parado.';if($('#backing-play'))$('#backing-play').textContent='▶ Tocar acompanhamento';document.querySelectorAll('[data-chord-tile]').forEach(t=>t.style.borderColor='')}
async function startBacking(){stopBacking();let a=ctx();await a.resume();let chords=extraLessons[state.chapter].chords;backingBeat=0;const tick=()=>{let index=Math.floor(backingBeat/4)%chords.length;if(backingBeat%4===0){let [o,q]=chords[index],intervals={maj:[0,4,7],min:[0,3,7],min7:[0,3,7,10],maj7:[0,4,7,11],dom:[0,4,7,10],pedal:[0,12]}[q],base=48+(state.key+o)%12;document.querySelectorAll('[data-chord-tile]').forEach((t,i)=>t.style.borderColor=i===index?'var(--copper)':'');intervals.forEach(n=>{let osc=a.createOscillator(),gain=a.createGain();osc.type='sine';osc.frequency.value=440*2**((base+n-69)/12);let now=a.currentTime,dur=60/bpm()*3.9;gain.gain.setValueAtTime(0,now);gain.gain.linearRampToValueAtTime(.045,now+.03);gain.gain.exponentialRampToValueAtTime(.001,now+dur);osc.connect(gain).connect(a.destination);osc.start(now);osc.stop(now+dur+.02);backingOsc.push(osc);osc.onended=()=>{backingOsc=backingOsc.filter(x=>x!==osc)}})}if($('#backing-status'))$('#backing-status').textContent='Compasso '+(index+1)+' · tempo '+(backingBeat%4+1)+' / 4';backingBeat++};tick();backingTimer=setInterval(tick,60000/bpm());$('#backing-play').textContent='↻ Reiniciar acompanhamento'}
function stop(){scheduled.forEach(o=>{try{o.stop()}catch{}});scheduled=[];clearTimeout(playTimer);animationTimers.forEach(clearTimeout);animationTimers=[];document.querySelectorAll('.fret g.playing').forEach(g=>g.classList.remove('playing'));document.querySelectorAll('#hear,#hear-ex,#hear-phrase').forEach(b=>b.disabled=false);if($('#play-status'))$('#play-status').textContent=''}
async function hear(notes,speed=state.speed||1){stop();let a=ctx();await a.resume();let step=60/bpm()/speed,now=a.currentTime+.08;notes.forEach((n,i)=>{tone(n.m,now+i*step,Math.min(.6,step*.85));animationTimers.push(setTimeout(()=>{document.querySelectorAll('.fret g.playing').forEach(g=>g.classList.remove('playing'));let g=document.querySelector('.fret g[data-string="'+n.s+'"][data-fret="'+n.f+'"]');if(g)g.classList.add('playing');if($('#play-status'))$('#play-status').textContent='Nota '+(i+1)+' de '+notes.length+' · '+strings[n.s]+' / casa '+n.f},80+i*step*1000))});document.querySelectorAll('#hear,#hear-ex,#hear-phrase').forEach(b=>b.disabled=true);playTimer=setTimeout(()=>{stop();if($('#play-status'))$('#play-status').textContent='Sua vez: repita, cante e crie uma variação.'},(notes.length*step+.2)*1000)}
function themeUpdate(){let dark=document.documentElement.dataset.theme==='dark';$('#theme-toggle').textContent=dark?'☀':'☾';$('#theme-toggle').setAttribute('aria-label',dark?'Ativar modo claro':'Ativar modo escuro');$('#theme-toggle').setAttribute('aria-pressed',String(dark))}
$('#theme-toggle').addEventListener('click',()=>{let theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('atlas-theme',theme)}catch{}themeUpdate()});themeUpdate();
document.addEventListener('click',e=>{let b=e.target.closest('button');if(b){if(b.dataset.chapter!==undefined||b.dataset.view||b.dataset.tab)stopBacking();if(b.id==='favorite'){saved['fav'+state.chapter]=!saved['fav'+state.chapter];persist();chapter()}if(b.id==='hear-phrase')hear(phraseNotes(),2);if(b.dataset.phrase!==undefined){stop();phraseIndex=+b.dataset.phrase;music()}if(b.id==='backing-play')startBacking();if(b.id==='backing-stop')stopBacking();if(b.dataset.answer!==undefined){let q=extraLessons[state.chapter].quiz;$('#quiz-result').textContent=(+b.dataset.answer===q.correct?'✓ Isso mesmo. ':'Ainda não. ')+q.why}if(b.id==='ear-new')earPlay(true);if(b.id==='ear-repeat')earPlay();if(b.dataset.ear){$('#ear-result').textContent=earQuestion?((b.dataset.ear===earQuestion.quality?'✓ Isso mesmo. ':'Ainda não. ')+'Você ouviu '+names[earQuestion.key]+(earQuestion.quality==='maj'?' maior: 1–3–5.':' menor: 1–♭3–5.')):'Sorteie e ouça um acorde primeiro.'}}
let g=e.target.closest('.fret-note');if(g){ctx().resume().then(()=>tone(+g.dataset.midi,ctx().currentTime,.7))}});
document.addEventListener('keydown',e=>{let g=e.target.closest&&e.target.closest('.fret-note');if(g&&(e.key==='Enter'||e.key===' ')){e.preventDefault();g.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
document.addEventListener('change',e=>{if(e.target.id==='pattern'){stop();state.pattern=e.target.value;lab()}if(e.target.id==='speed'){stop();state.speed=+e.target.value;lab()}if(['key','type','pos','bpm'].includes(e.target.id))stopBacking()});document.addEventListener('click',e=>{if(e.target.closest('#minus,#plus'))stopBacking()});
render();
